{
  "code": "/* Form states and keyboard focus */
#search:focus-visible {
  outline: none;
}

#search-container:focus-within {
  box-shadow: 0 0 0 2px var(--color-primary-purple);
}

.chip:focus-visible {
  outline: 2px solid var(--color-primary-purple);
  outline-offset: 2px;
}

.action-btn:focus-visible,
.fav-btn:focus-visible {
  outline: 2px solid var(--color-text-heading);
  outline-offset: 2px;
}

/* Hidden and disabled states */
[hidden] {
  display: none !important;
}

.mentor-card[aria-disabled="true"] {
  opacity: 0.7;
  pointer-events: none;
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  .chip,
  .action-btn,
  .fav-btn {
    transition: none;
  }
}

/* Mobile 390px */
@media (max-width: 390px) {
  #mentor-discovery-page {
    padding: var(--spacing-md) var(--spacing-sm);
  }

  .card-footer {
    flex-wrap: wrap;
    gap: var(--spacing-sm);
  }

  .action-btn {
    flex: 1;
    text-align: center;
  }
}

/* Mobile 320px */
@media (max-width: 320px) {
  #page-title {
    font-size: 20px;
  }

  .mentor-card {
    padding: var(--spacing-sm);
  }

  .card-header {
    flex-direction: column;
    align-items: flex-start;
    gap: var(--spacing-sm);
  }

  .avatar {
    width: 48px;
    height: 48px;
  }

  .metadata {
    flex-direction: column;
    gap: var(--spacing-xs);
  }

  .card-footer {
    flex-direction: column;
    align-items: stretch;
  }

  .fav-btn {
    align-self: flex-end;
    margin-top: var(--spacing-sm);
  }
}"
}
